"""Interest rate conversions: APR <-> APY with discrete and continuous compounding."""

import math
import sys


def apy_from_apr(apr: float, periods_per_year: int) -> float:
    """Effective annual yield from nominal APR compounded periods_per_year times."""
    return (1.0 + apr / periods_per_year) ** periods_per_year - 1.0


def apr_from_apy(apy: float, periods_per_year: int) -> float:
    """Nominal APR (compounded periods_per_year times) equivalent to an APY."""
    return periods_per_year * ((1.0 + apy) ** (1.0 / periods_per_year) - 1.0)


def apy_from_apr_continuous(apr: float) -> float:
    """Effective annual yield under continuous compounding: e^apr - 1."""
    return math.exp(apr) - 1.0


def apr_from_apy_continuous(apy: float) -> float:
    """Continuously compounded APR equivalent to an APY: ln(1 + apy)."""
    return math.log(1.0 + apy)


def main(argv):
    if len(argv) != 4 or argv[1] not in {"apy", "apr", "apy-cont", "apr-cont"}:
        print(
            "usage:\n"
            "  python rates.py apy <apr> <periods_per_year>\n"
            "  python rates.py apr <apy> <periods_per_year>\n"
            "  python rates.py apy-cont <apr>\n"
            "  python rates.py apr-cont <apy>",
            file=sys.stderr,
        )
        return 2
    mode = argv[1]
    if mode == "apy":
        print(f"{apy_from_apr(float(argv[2]), int(argv[3])):.6f}")
    elif mode == "apr":
        print(f"{apr_from_apy(float(argv[2]), int(argv[3])):.6f}")
    elif mode == "apy-cont":
        print(f"{apy_from_apr_continuous(float(argv[2])):.6f}")
    else:
        print(f"{apr_from_apy_continuous(float(argv[2])):.6f}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

