import math

import pytest

from rates import (
    apy_from_apr,
    apy_from_apr_continuous,
    apr_from_apy,
    apr_from_apy_continuous,
)

PERIODS = [1, 2, 4, 12, 52, 365]


def test_monthly_12pct():
    assert round(apy_from_apr(0.12, 12), 6) == 0.126825


@pytest.mark.parametrize("periods", PERIODS)
def test_inverse_grid(periods):
    for pct in range(1, 31):
        apr = pct / 100.0
        assert apr_from_apy(apy_from_apr(apr, periods), periods) == pytest.approx(
            apr, abs=1e-12
        )
        assert apy_from_apr(apr_from_apy(apr, periods), periods) == pytest.approx(
            apr, abs=1e-12
        )


def test_continuous():
    assert apy_from_apr_continuous(0.10) == pytest.approx(math.exp(0.10) - 1.0)
    assert apr_from_apy_continuous(math.exp(0.10) - 1.0) == pytest.approx(0.10)

